syntax:
struct MyStruct {
  int a : 5; // 5-bit integer
  unsigned int b : 11; // 11-bit unsigned integer
  int : 0; // Anonymous bitfield for padding
  unsigned int c : 8; // 8-bit unsigned integer
  int d : 8; // 8-bit integer
  struct { int ee : 8; } e; // Nested bitfield struct
};

code_example:
#include <iostream>
#include <bitset>
struct MyStruct {
  int a : 5;
  unsigned int b : 11;
  int : 0;
  unsigned int c : 8;
  int d : 8;
  struct { int ee : 8; } e;
};

int main() {
  MyStruct s = {15, 1023, 255, 128, {100}};
  std::cout << std::bitset<32>(reinterpret_cast<unsigned int&>(s.a)) << std::endl; //Shows the bit representation of 'a', compiler dependent
  std::cout << s.a << " " << s.b << " " << s.c << " " << s.d << " " << s.e.ee << std::endl;
  return 0;
}
